// Fixtures for the theme tests: what the TS implementation resolves, generated
// once from it and checked in under Fixtures/theme/.
//
// Generated by running the TS app's own code (model/colorTheme.ts,
// model/colorDefaults.generated.ts, main/shell/colorThemeCatalog.ts) over the
// pinned vscode submodule's built-in theme extensions — the same files
// vendored in Sources/DevHubCore/Theme/BuiltinThemes — with a throwaway
// script outside native/ (no JavaScript lives here):
//
//   builtin-themes.json  every built-in theme: its entry, definition (includes
//                        folded), shell palette, terminal palette, and the css
//                        of every colour id in the defaults table
//   color-math.json      800 pseudo-random colours through every Color op
//   registry.json        a synthetic defaults table exercising every
//                        transform, resolved under each theme type
//
// Regenerate them whenever the vendored themes or the defaults table change.

import Foundation

enum ThemeFixtures {
    static let directory = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .deletingLastPathComponent()
        .appendingPathComponent("Fixtures")
        .appendingPathComponent("theme")

    static func data(_ name: String) throws -> Data {
        try Data(contentsOf: directory.appendingPathComponent(name))
    }

    struct BuiltinTheme: Decodable {
        let settingsId: String
        let label: String
        let id: String?
        let uiTheme: String?
        let `extension`: String
        let path: String
        let type: String
        let colors: [String: String]
        let shell: Shell
        let terminal: Terminal
        let css: [String: String?]
    }

    struct Shell: Decodable, Equatable {
        let base: String
        let surface: String
        let chrome: String
        let canvas: String
        let ink: String
    }

    struct Terminal: Decodable, Equatable {
        let background: String
        let foreground: String
        let cursor: String
        let cursorText: String
        let selectionBackground: String
        let selectionForeground: String?
        let ansi: [String]
    }

    static func builtinThemes() throws -> [BuiltinTheme] {
        try JSONDecoder().decode([BuiltinTheme].self, from: data("builtin-themes.json"))
    }

    struct MathCase: Decodable {
        let a: String
        let b: String
        let f: Double
        let toString: String
        let luminance: Double
        let lighten: String
        let darken: String
        let lightenDarken: String
        let transparent: String
        let mix: String
        let mixDefault: String
        let opaque: String
        let lighter: String
        let darker: String
        let lighterDefault: String
        let darkerDefault: String
    }

    struct HexCase: Decodable {
        let text: String
        let toString: String
    }

    struct ColorMath: Decodable {
        let hex: [HexCase]
        let cases: [MathCase]
    }

    static func colorMath() throws -> ColorMath {
        try JSONDecoder().decode(ColorMath.self, from: data("color-math.json"))
    }
}
